B.JE=new A.br("dart-03-tipos-datos","Dart b\xe1sico","03 \xb7 Tipos de datos b\xe1sicos","Principiante","Trabaja con int, double, num, String, bool, Object y dynamic.","Un tipo correcto documenta el c\xf3digo y evita operaciones inv\xe1lidas.","void main() {\n  int unidades = 4;\n  double precio = 19.95;\n  num descuento = 5;\n  String categoria = 'Libros';\n  bool disponible = true;\n  Object dato = 'texto seguro';\n  dynamic flexible = 10;\n\n  print(unidades.runtimeType);\n  print('$categoria - $disponible');\n  print(dato);\n  print(flexible);\n}",B.Wp,"Representa un estudiante con nombre, edad, promedio, estado activo y c\xf3digo.",B.V0,4284524026)
B.TM=s(["Usa +, -, *, /, ~/ y %.","Compara con ==, !=, >, <, >= y <=.","Combina con &&, || y !.","Usa el ternario para decisiones peque\xf1as."],t.s)
