B.Op=new A.bX("AnimatedContainer(\n  duration: const Duration(milliseconds: 220),\n  curve: Curves.easeOut,\n  padding: EdgeInsets.all(selected ? 20 : 12),\n  decoration: BoxDecoration(\n    borderRadius: BorderRadius.circular(selected ? 24 : 14),\n  ),\n  child: child,\n)",B.Us,B.Qp,B.RS,B.Ul)
B.QB=s(["InkWell ofrece feedback Material para taps y debe preferirse en superficies Material.","GestureDetector reconoce gestos sin a\xf1adir feedback visual autom\xe1ticamente.","Focus y FocusNode permiten controlar navegaci\xf3n con teclado.","Una interacci\xf3n accesible ofrece m\xe1s de una forma de descubrir y ejecutar acciones importantes."],t.s)
B.Ps=new A.aO("Tap con feedback Material","InkWell dibuja ripple y respeta el radio configurado.","Material(\n  borderRadius: BorderRadius.circular(16),\n  child: InkWell(\n    borderRadius: BorderRadius.circular(16),\n    onTap: open,\n    child: const Padding(\n      padding: EdgeInsets.all(16),\n      child: Text('Detalle'),\n    ),\n  ),\n)","")
B.PE=new A.aO("Mover foco","TextInputAction permite que el teclado avance naturalmente entre campos.","TextFormField(\n  textInputAction: TextInputAction.next,\n  onFieldSubmitted: (_) => nextFocus.requestFocus(),\n)","")
B.Ve=s([B.Ps,B.PE],t.W)
B.Vd=s(["Usar GestureDetector en un bot\xf3n sin feedback, tooltip ni sem\xe1ntica.","Crear FocusNode dentro de build.","Hacer acciones disponibles solo con swipe o long press sin alternativa visible."],t.s)
B.a1o=new A.ab("Tarjeta accesible","Haz una tarjeta accionable con mouse, touch y teclado.","Combina Material, InkWell y Focus.")
B.a1g=new A.ab("Formulario con foco","Haz que Next avance entre tres campos y Done env\xede el formulario.","Usa TextInputAction y FocusNode.")
B.a0j=new A.ab("Acci\xf3n alternativa","Si tienes una acci\xf3n en long press, a\xf1ade otra forma visible de ejecutarla.","Un men\xfa contextual o IconButton puede ser suficiente.")
